// ============================================================================
// load-v5-content.js: put the v5 site's text into the admin database
// GENERATED by the frontend repo (scripts/export-v5-cms.ts). Do not edit by hand:
// change the frontend content and generate again.
//
// The admin's text wins over the site's built-in text, so entries holding old-site
// text would replace the v5 text. This script:
//   1. v5 page text (home hero, pricing, contact, login/signup, Custom LMS):
//      creates missing entries; with OVERWRITE, replaces the old text.
//   2. Company facts (About, contact details): creates missing entries; with
//      OVERWRITE, only fills fields that are empty. Never replaces filled-in facts.
//   3. Legal pages: with OVERWRITE, updates the text where the database has a copy.
//      Missing ones are not created (the site then shows its own v5 text).
//   4. SEO per page: creates missing entries with the v5 title and description;
//      with OVERWRITE, replaces old titles/descriptions. Share image, keywords and
//      noindex are never changed.
// Never touched: prices, testimonials, client logos, site identity, app links,
// address, footer, Settings > Pages.
//
// Every document it changes is copied to the "cms_backup_v5" collection first.
//
// The current live site (old frontend) shares this database until the v5 launch.
// Entries it reads (LIVE_SITE_READS) are left alone unless AT_LAUNCH = true.
//
// DRY RUN by default. Set APPLY = true to write.
// Usage: mongosh "$MONGO_URL" --quiet load-v5-content.js
// ============================================================================

const APPLY = false; // write to the database
const OVERWRITE = false; // also update entries that already exist
const AT_LAUNCH = false; // also touch entries the old live site reads (only at the v5 launch)

const LIVE_SITE_READS = {
  cms: ["pricing-hero"],
  seos: ["home", "features", "pricing", "about"],
};

const TEXT = /*__TEXT__*/[];
const FACTS = /*__FACTS__*/[];
const LEGAL = /*__LEGAL__*/[];
const SEO = /*__SEO__*/[];

const now = new Date();
const backups = db.getCollection("cms_backup_v5");
const short = (v) => {
  const s = typeof v === "string" ? v : JSON.stringify(v);
  return s === undefined ? "(empty)" : s.length > 90 ? s.slice(0, 87) + "..." : s;
};
const blocked = (collection, slug) => !AT_LAUNCH && (LIVE_SITE_READS[collection] || []).includes(slug);
const backup = (collection, doc) => APPLY && backups.insertOne({ collection, slug: doc.slug, savedAt: now, doc });
const isEmpty = (v) => v === undefined || v === null || (typeof v === "string" && v.trim() === "") || (Array.isArray(v) && v.length === 0);
const counts = { create: 0, update: 0, skip: 0 };

function create(collection, doc) {
  counts.create++;
  print("   + create " + doc.slug);
  if (APPLY) db.getCollection(collection).insertOne({ ...doc, isActive: true, isDeleted: false, createdAt: now, updatedAt: now });
}

function update(collection, existing, set) {
  const changed = Object.keys(set).filter((k) => JSON.stringify(existing[k]) !== JSON.stringify(set[k]));
  if (!changed.length) {
    counts.skip++;
    print("   = same    " + existing.slug);
    return;
  }
  counts.update++;
  print("   ~ update  " + existing.slug);
  for (const k of changed) print("       " + k + ": " + short(existing[k]) + "  ->  " + short(set[k]));
  if (!APPLY) return;
  backup(collection, existing);
  db.getCollection(collection).updateOne({ _id: existing._id }, { $set: { ...set, updatedAt: now } });
}

print("Database: " + db.getName() + "   " + (APPLY ? "[APPLY]" : "[DRY RUN: nothing is written]") + (OVERWRITE ? " [OVERWRITE]" : "") + (AT_LAUNCH ? " [AT_LAUNCH]" : ""));

print("\n== 1. v5 page text (cms)");
for (const entry of TEXT) {
  if (blocked("cms", entry.slug)) { counts.skip++; print("   - skip    " + entry.slug + " (old live site reads it; AT_LAUNCH)"); continue; }
  const existing = db.cms.findOne({ slug: entry.slug });
  if (!existing) create("cms", entry);
  else if (OVERWRITE) { const { slug, ...set } = entry; update("cms", existing, set); }
  else { counts.skip++; print("   - exists  " + entry.slug + " (OVERWRITE to replace)"); }
}

print("\n== 2. Company facts (cms): filled-in fields are kept");
for (const entry of FACTS) {
  const existing = db.cms.findOne({ slug: entry.slug });
  if (!existing) { create("cms", entry); continue; }
  if (!OVERWRITE) { counts.skip++; print("   - exists  " + entry.slug + " (OVERWRITE to fill empty fields)"); continue; }
  const data = { ...(existing.data || {}) };
  for (const [k, v] of Object.entries(entry.data)) if (isEmpty(data[k])) data[k] = v;
  update("cms", existing, { data });
}

print("\n== 3. Legal pages (cms): only where a copy exists");
for (const entry of LEGAL) {
  const existing = db.cms.findOne({ slug: entry.slug });
  if (!existing) { counts.skip++; print("   - none    " + entry.slug + " (site shows its own v5 text)"); continue; }
  if (!OVERWRITE) { counts.skip++; print("   - exists  " + entry.slug + " (OVERWRITE to replace)"); continue; }
  update("cms", existing, { title: entry.title, content: entry.content });
}

print("\n== 4. SEO per page (seos)");
for (const entry of SEO) {
  if (blocked("seos", entry.slug)) { counts.skip++; print("   - skip    " + entry.slug + " (old live site reads it; AT_LAUNCH)"); continue; }
  const existing = db.seos.findOne({ slug: entry.slug });
  if (!existing) create("seos", { ...entry, metakeyword: [], othermetatag: [], ogImage: "", noindex: entry.slug === "login" || entry.slug === "signup" });
  else if (OVERWRITE) update("seos", existing, { metatitle: entry.metatitle, metadescription: entry.metadescription });
  else { counts.skip++; print("   - exists  " + entry.slug + " (OVERWRITE to replace)"); }
}

print("\n" + (APPLY ? "Done" : "Dry run") + ": " + counts.create + " to create, " + counts.update + " to update, " + counts.skip + " skipped." + (APPLY && counts.update ? " Old versions are in cms_backup_v5." : ""));
